/* Linear interpolation over a real measured curve, stored as a flat
   [wavelength, transmission, wavelength, transmission, ...] array to keep
   the embedded data compact. Clamps at the ends rather than extrapolating --
   the real dataset's own edge value is a better guess than inventing a
   trend past where it was actually measured. */
function realCurveT(curve, l) {
  const n = curve.length;
  if (l <= curve[0]) return curve[1];
  if (l >= curve[n - 2]) return curve[n - 1];
  for (let i = 0; i < n - 2; i += 2) {
    const x0 = curve[i], x1 = curve[i + 2];
    if (l >= x0 && l <= x1) {
      const y0 = curve[i + 1], y1 = curve[i + 3];
      return y0 + (l - x0) / (x1 - x0) * (y1 - y0);
    }
  }
  return curve[n - 1];
}
